mapper.select:
SELECT po.payment_obligation_id, po.participant_id, po.expected_amount, po.payment_status, po.review_status, po.obligation_status FROM payment_obligation po INNER JOIN ( SELECT participant_id, MAX(payment_obligation_id) AS latest_id FROM payment_obligation WHERE participant_id IN
#{id}
AND obligation_status = 'ACTIVE' GROUP BY participant_id ) latest ON latest.participant_id = po.participant_id AND latest.latest_id = po.payment_obligation_id

SELECT payment_obligation_id, participant_id, expected_amount, payment_status, review_status, obligation_status, overdue_since FROM payment_obligation WHERE participant_id IN
#{id}
AND payment_status != 'PAID' AND obligation_status = 'ACTIVE' AND overdue_since IS NULL

mapper.update:
UPDATE payment_obligation
SET overdue_since = NULL
WHERE payment_obligation_id = #{paymentObligationId}

UPDATE payment_obligation SET overdue_since = #{overdueSince} WHERE payment_obligation_id IN
#{id}
AND payment_status != 'PAID' AND overdue_since IS NULL AND obligation_status = 'ACTIVE'
